namespace sv_488a1d4b1dee4132a9e80e547cef01f6.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@namespace sv_488a1d4b1dee4132a9e80e547cef01f6.Components.Pages.Apply

<nav aria-label="Application progress" class="step-indicator mb-4">
    <ol class="d-flex list-unstyled justify-content-between p-0 m-0 position-relative">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var isCompleted = stepIndex < CurrentStep;
            var isCurrent = stepIndex == CurrentStep;
            var isFuture = stepIndex > CurrentStep;

            <li class="step-item text-center flex-fill @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "") @(isFuture ? "dimmed" : "")"
                @onclick="() => OnStepClick(stepIndex)"
                role="button"
                aria-current="@(isCurrent ? "step" : null)">
                <div class="step-circle mx-auto mb-1 d-flex align-items-center justify-content-center rounded-circle
                    @(isCompleted ? "bg-success text-white" : isCurrent ? "bg-primary text-white" : "bg-light text-muted border")">
                    @if (isCompleted)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <small class="@(isFuture ? "text-muted" : isCurrent ? "fw-bold text-primary" : "text-success")">
                    @StepNames[stepIndex]
                </small>
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public List<string> StepNames { get; set; } = [];
    [Parameter] public EventCallback<int> OnStepSelected { get; set; }

    private async Task OnStepClick(int step)
    {
        if (step < CurrentStep)
        {
            await OnStepSelected.InvokeAsync(step);
        }
    }
}

.step-circle {
    width: 36px;
    height: 36px;
    font-size: 0.9rem;
    transition: background-color 0.2s, color 0.2s;
}

.step-item {
    cursor: default;
    position: relative;
}

.step-item.completed {
    cursor: pointer;
}

.step-item.dimmed {
    opacity: 0.5;
}

@namespace sv_488a1d4b1dee4132a9e80e547cef01f6.Components.Pages.Apply

<div class="card">
    <div class="card-header"><h5 class="mb-0">Personal Information</h5></div>
    <div class="card-body">
        <div class="mb-3">
            <label class="form-label">Full Name <span class="text-danger">*</span></label>
            <input class="form-control @(Errors.ContainsKey("FullName") ? "is-invalid" : "")"
                   @bind="FullName" @bind:event="oninput" placeholder="Enter your full name" />
            @if (Errors.ContainsKey("FullName"))
            {
                <div class="invalid-feedback">@Errors["FullName"]</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label">Email <span class="text-danger">*</span></label>
            <input type="email" class="form-control @(Errors.ContainsKey("Email") ? "is-invalid" : "")"
                   @bind="Email" @bind:event="oninput" placeholder="you@example.com" />
            @if (Errors.ContainsKey("Email"))
            {
                <div class="invalid-feedback">@Errors["Email"]</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label">Phone <span class="text-danger">*</span></label>
            <input type="tel" class="form-control @(Errors.ContainsKey("Phone") ? "is-invalid" : "")"
                   @bind="Phone" @bind:event="oninput" placeholder="(555) 123-4567" />
            @if (Errors.ContainsKey("Phone"))
            {
                <div class="invalid-feedback">@Errors["Phone"]</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label">Address <span class="text-danger">*</span></label>
            <textarea class="form-control @(Errors.ContainsKey("Address") ? "is-invalid" : "")"
                      @bind="Address" @bind:event="oninput" rows="2" placeholder="Your mailing address"></textarea>
            @if (Errors.ContainsKey("Address"))
            {
                <div class="invalid-feedback">@Errors["Address"]</div>
            }
        </div>

        @if (!string.IsNullOrEmpty(EmailValidationError))
        {
            <div class="alert alert-danger">@EmailValidationError</div>
        }

        <div class="d-flex justify-content-end">
            <button class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
                @if (IsValidating)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                    <span>Validating…</span>
                }
                else
                {
                    <span>Next</span>
                }
            </button>
        </div>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public EventCallback<(string FullName, string Email, string Phone, string Address)> OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private Dictionary<string, string> Errors { get; set; } = new();
    private string? EmailValidationError { get; set; }
    private bool IsValidating { get; set; }

    private async Task HandleNext()
    {
        Errors.Clear();
        EmailValidationError = null;

        if (string.IsNullOrWhiteSpace(FullName))
            Errors["FullName"] = "Full name is required.";
        if (string.IsNullOrWhiteSpace(Email))
            Errors["Email"] = "Email is required.";
        if (string.IsNullOrWhiteSpace(Phone))
            Errors["Phone"] = "Phone is required.";
        if (string.IsNullOrWhiteSpace(Address))
            Errors["Address"] = "Address is required.";

        if (Errors.Count > 0)
            return;

        if (ValidateEmail is not null)
        {
            IsValidating = true;
            try
            {
                var isValid = await ValidateEmail(Email);
                if (!isValid)
                {
                    EmailValidationError = "The email address could not be validated. Please check and try again.";
                    return;
                }
            }
            finally
            {
                IsValidating = false;
            }
        }

        await OnNext.InvokeAsync((FullName, Email, Phone, Address));
    }
}

@namespace sv_488a1d4b1dee4132a9e80e547cef01f6.Components.Pages.Apply

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-3">
            <h6 class="mb-0">Position @(Index + 1)</h6>
            @if (CanRemove)
            {
                <button class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
            }
        </div>

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Company Name <span class="text-danger">*</span></label>
                <input class="form-control" value="@Entry.Company"
                       @oninput="e => Update(Entry with { Company = (string?)e.Value ?? "" })" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Job Title <span class="text-danger">*</span></label>
                <input class="form-control" value="@Entry.Title"
                       @oninput="e => Update(Entry with { Title = (string?)e.Value ?? "" })" />
            </div>
            <div class="col-md-4">
                <label class="form-label">Start Date <span class="text-danger">*</span></label>
                <input type="date" class="form-control" value="@FormatDate(Entry.StartDate)"
                       @onchange="e => Update(Entry with { StartDate = ParseDate((string?)e.Value) })" />
            </div>
            <div class="col-md-4">
                <label class="form-label">End Date</label>
                <input type="date" class="form-control" value="@FormatDate(Entry.EndDate)"
                       disabled="@IsCurrent"
                       @onchange="e => Update(Entry with { EndDate = ParseNullableDate((string?)e.Value) })" />
            </div>
            <div class="col-md-4 d-flex align-items-end">
                <div class="form-check mb-2">
                    <input class="form-check-input" type="checkbox" id="current-@Index"
                           checked="@IsCurrent" @onchange="HandleCurrentChanged" />
                    <label class="form-check-label" for="current-@Index">Currently work here</label>
                </div>
            </div>
            <div class="col-12">
                <label class="form-label">Description</label>
                <textarea class="form-control" rows="3" value="@Entry.Description"
                          @oninput="e => Update(Entry with { Description = (string?)e.Value ?? "" })"></textarea>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.IsCurrent;

    private async Task Update(WorkEntryModel updated) => await OnChanged.InvokeAsync(updated);

    private async Task HandleCurrentChanged(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        var updated = Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate };
        await OnChanged.InvokeAsync(updated);
    }

    private static string FormatDate(DateTime? date) => date?.ToString("yyyy-MM-dd") ?? "";
    private static string FormatDate(DateTime date) => date == default ? "" : date.ToString("yyyy-MM-dd");
    private static DateTime ParseDate(string? value) => DateTime.TryParse(value, out var d) ? d : default;
    private static DateTime? ParseNullableDate(string? value) => DateTime.TryParse(value, out var d) ? d : null;
}

@namespace sv_488a1d4b1dee4132a9e80e547cef01f6.Components.Pages.Apply

<div class="card">
    <div class="card-header"><h5 class="mb-0">Work History</h5></div>
    <div class="card-body">
        @for (int i = 0; i < Entries.Count; i++)
        {
            var index = i;
            <WorkEntryForm Entry="Entries[index]"
                           Index="index"
                           CanRemove="Entries.Count > 1"
                           OnChanged="entry => HandleEntryChanged(index, entry)"
                           OnRemove="() => HandleRemove(index)" />
        }

        <button class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
            <span class="me-1">+</span> Add Another Position
        </button>

        @if (!string.IsNullOrEmpty(ValidationError))
        {
            <div class="alert alert-danger">@ValidationError</div>
        }

        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="OnBack">Back</button>
            <button class="btn btn-primary" @onclick="HandleNext">Next</button>
        </div>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntryModel> Entries { get; set; } = [];
    [Parameter] public EventCallback<List<WorkEntryModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<List<WorkEntryModel>> OnEntriesChanged { get; set; }

    private string? ValidationError;

    private async Task HandleEntryChanged(int index, WorkEntryModel updated)
    {
        var list = new List<WorkEntryModel>(Entries);
        list[index] = updated;
        await OnEntriesChanged.InvokeAsync(list);
    }

    private async Task HandleRemove(int index)
    {
        var list = new List<WorkEntryModel>(Entries);
        list.RemoveAt(index);
        await OnEntriesChanged.InvokeAsync(list);
    }

    private async Task AddEntry()
    {
        var list = new List<WorkEntryModel>(Entries) { new() };
        await OnEntriesChanged.InvokeAsync(list);
    }

    private async Task HandleNext()
    {
        ValidationError = null;
        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) || entry.StartDate == default)
            {
                ValidationError = "Each position requires a company name, job title, and start date.";
                return;
            }
        }
        await OnNext.InvokeAsync(Entries);
    }
}

