    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.IsCurrent;

    private async Task Update(WorkEntryModel updated) => await OnChanged.InvokeAsync(updated);

    private async Task HandleCurrentChanged(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        var updated = Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate };
        await OnChanged.InvokeAsync(updated);
    }

    private static string FormatDate(DateTime? date) => date?.ToString("yyyy-MM-dd") ?? "";
    private static string FormatDate(DateTime date) => date == default ? "" : date.ToString("yyyy-MM-dd");
    private static DateTime ParseDate(string? value) => DateTime.TryParse(value, out var d) ? d : default;
    private static DateTime? ParseNullableDate(string? value) => DateTime.TryParse(value, out var d) ? d : null;
}

