@namespace sv_488a1d4b1dee4132a9e80e547cef01f6.Components.Pages.Apply

<div class="card">
    <div class="card-header"><h5 class="mb-0">References</h5></div>
    <div class="card-body">
        @for (int i = 0; i < References.Count; i++)
        {
            var index = i;
            <ReferenceForm Reference="References[index]"
                           Index="index"
                           CanRemove="References.Count > 2"
                           OnChanged="r => HandleChanged(index, r)"
                           OnRemove="() => HandleRemove(index)" />
        }

        @if (References.Count < 3)
        {
            <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">
                <span class="me-1">+</span> Add Reference
            </button>
        }

        @if (!string.IsNullOrEmpty(ValidationError))
        {
            <div class="alert alert-danger">@ValidationError</div>
        }

        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="OnBack">Back</button>
            <button class="btn btn-primary" @onclick="HandleNext">Next</button>
        </div>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = [];
    [Parameter] public EventCallback<List<ReferenceModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<List<ReferenceModel>> OnReferencesChanged { get; set; }

    private string? ValidationError;

    private async Task HandleChanged(int index, ReferenceModel updated)
    {
        var list = new List<ReferenceModel>(References);
        list[index] = updated;
        await OnReferencesChanged.InvokeAsync(list);
    }

    private async Task HandleRemove(int index)
    {
        var list = new List<ReferenceModel>(References);
        list.RemoveAt(index);
        await OnReferencesChanged.InvokeAsync(list);
    }

    private async Task AddReference()
    {
        if (References.Count >= 3) return;
        var list = new List<ReferenceModel>(References) { new() };
        await OnReferencesChanged.InvokeAsync(list);
    }

    private async Task HandleNext()
    {
        ValidationError = null;
        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                ValidationError = "All reference fields are required.";
                return;
            }
        }
        await OnNext.InvokeAsync(References);
    }
}

