@namespace sv_488a1d4b1dee4132a9e80e547cef01f6.Components.Pages.Apply

<div class="card">
    <div class="card-header"><h5 class="mb-0">Review &amp; Submit</h5></div>
    <div class="card-body">

        @* Personal Info *@
        <div class="mb-4">
            <div class="d-flex justify-content-between align-items-center">
                <h6>Personal Information</h6>
                <button class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
            </div>
            <dl class="row mb-0">
                <dt class="col-sm-3">Name</dt>
                <dd class="col-sm-9">@Personal.FullName</dd>
                <dt class="col-sm-3">Email</dt>
                <dd class="col-sm-9">@Personal.Email</dd>
                <dt class="col-sm-3">Phone</dt>
                <dd class="col-sm-9">@Personal.Phone</dd>
                <dt class="col-sm-3">Address</dt>
                <dd class="col-sm-9">@Personal.Address</dd>
            </dl>
        </div>
        <hr />

        @* Work History *@
        <div class="mb-4">
            <div class="d-flex justify-content-between align-items-center">
                <h6>Work History</h6>
                <button class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="mb-2 ps-2 border-start border-3">
                    <strong>@entry.Title</strong> at @entry.Company<br />
                    <small class="text-muted">
                        @entry.StartDate.ToString("MMM yyyy") –
                        @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                    </small>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p class="mb-0 mt-1">@entry.Description</p>
                    }
                </div>
            }
        </div>
        <hr />

        @* References *@
        <div class="mb-4">
            <div class="d-flex justify-content-between align-items-center">
                <h6>References</h6>
                <button class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="mb-2">
                    <strong>@r.Name</strong> — @r.Relationship<br />
                    <small class="text-muted">@r.Email · @r.Phone</small>
                </div>
            }
        </div>
        <hr />

        @* Cover Letter *@
        <div class="mb-4">
            <div class="d-flex justify-content-between align-items-center">
                <h6>Cover Letter</h6>
                <button class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            <p class="mb-0" style="white-space: pre-wrap;">@CoverLetter</p>
        </div>
        <hr />

        @if (!string.IsNullOrEmpty(SubmitError))
        {
            <div class="alert alert-danger">@SubmitError</div>
        }

        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="OnBack">Back</button>
            <button class="btn btn-success btn-lg" @onclick="OnSubmit" disabled="@IsSubmitting">
                @if (IsSubmitting)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                    <span>Submitting…</span>
                }
                else
                {
                    <span>Submit Application</span>
                }
            </button>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public (string FullName, string Email, string Phone, string Address) Personal { get; set; }
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = [];
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = [];
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public string? SubmitError { get; set; }
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
}

