@page "/apply"
@rendermode InteractiveServer
@namespace sv_488a1d4b1dee4132a9e80e547cef01f6.Components.Pages.Apply
@using sv_488a1d4b1dee4132a9e80e547cef01f6.Models
@inject IApplicationService AppService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4 text-center">Job Application</h2>

    @if (SubmittedId.HasValue)
    {
        <div class="alert alert-success text-center">
            <h4 class="alert-heading">Application Submitted!</h4>
            <p class="mb-0">Your application ID is <strong>#@SubmittedId</strong>. We'll be in touch soon.</p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="CurrentStep" StepNames="StepNames" OnStepSelected="GoToStep" />

        @switch (CurrentStep)
        {
            case 0:
                <PersonalInfoStep FullName="@PersonalFullName" Email="@PersonalEmail"
                                  Phone="@PersonalPhone" Address="@PersonalAddress"
                                  ValidateEmail="AppService.ValidateEmailAsync"
                                  OnNext="HandlePersonalNext" />
                break;

            case 1:
                <WorkHistoryStep Entries="WorkEntries"
                                 OnEntriesChanged="entries => WorkEntries = entries"
                                 OnNext="HandleWorkNext" OnBack="() => GoToStep(0)" />
                break;

            case 2:
                <ReferencesStep References="References"
                                OnReferencesChanged="refs => References = refs"
                                OnNext="HandleReferencesNext" OnBack="() => GoToStep(1)" />
                break;

            case 3:
                <CoverLetterStep CoverLetter="@CoverLetterText"
                                 OnNext="HandleCoverLetterNext" OnBack="() => GoToStep(2)" />
                break;

            case 4:
                <ReviewStep Personal="(PersonalFullName, PersonalEmail, PersonalPhone, PersonalAddress)"
                            WorkEntries="WorkEntries" References="References"
                            CoverLetter="@CoverLetterText"
                            IsSubmitting="IsSubmitting" SubmitError="@SubmitError"
                            OnEditStep="GoToStep" OnSubmit="HandleSubmit"
                            OnBack="() => GoToStep(3)" />
                break;
        }
    }
</div>

@code {
    private static readonly List<string> StepNames =
    [
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    ];

    private int CurrentStep { get; set; }
    private int? SubmittedId { get; set; }
    private bool IsSubmitting { get; set; }
    private string? SubmitError { get; set; }

    // Step 1 state
    private string PersonalFullName { get; set; } = "";
    private string PersonalEmail { get; set; } = "";
    private string PersonalPhone { get; set; } = "";
    private string PersonalAddress { get; set; } = "";

    // Step 2 state
    private List<WorkEntryModel> WorkEntries { get; set; } = [new()];

    // Step 3 state
    private List<ReferenceModel> References { get; set; } = [new(), new()];

    // Step 4 state
    private string CoverLetterText { get; set; } = "";

    private void GoToStep(int step) => CurrentStep = step;

    private void HandlePersonalNext((string FullName, string Email, string Phone, string Address) data)
    {
        PersonalFullName = data.FullName;
        PersonalEmail = data.Email;
        PersonalPhone = data.Phone;
        PersonalAddress = data.Address;
        CurrentStep = 1;
    }

    private void HandleWorkNext(List<WorkEntryModel> entries)
    {
        WorkEntries = entries;
        CurrentStep = 2;
    }

    private void HandleReferencesNext(List<ReferenceModel> refs)
    {
        References = refs;
        CurrentStep = 3;
    }

    private void HandleCoverLetterNext(string coverLetter)
    {
        CoverLetterText = coverLetter;
        CurrentStep = 4;
    }

    private async Task HandleSubmit()
    {
        IsSubmitting = true;
        SubmitError = null;

        try
        {
            var personal = new PersonalInfo(PersonalFullName, PersonalEmail, PersonalPhone, PersonalAddress);

            var workEntries = WorkEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList();

            var references = References.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

            var application = new JobApplication(personal, new WorkHistory(workEntries), references, CoverLetterText);
            SubmittedId = await AppService.SubmitApplicationAsync(application);
        }
        catch (Exception ex)
        {
            SubmitError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}

